e permission"]},{"id":"2tywmjis","type":"short_text","required":true,"section":"Security Deposit Refund","label":"Who should we write your Security Deposit refund check to?","placeholder":"First and Last Name"},{"id":"qwb19pxp","type":"short_text","required":true,"section":"Security Deposit Refund","label":"Where should we mail the Security Deposit refund check?","placeholder":"Street Address, City, State, Zip"}]$j$::jsonb where id = 'e9be06b9-6788-41bc-a78a-28e02b8b749a' returning jsonb_array_length(fields) n;
